# Standalone, stdlib-only (fractions/math), fail-closed: raises on ANY failed check.
# verify(witness) is the entrypoint; no filesystem, no network, no print, no subprocess.
from fractions import Fraction
from math import factorial, gcd

class VerificationError(Exception):
    pass

def verify(witness):
    N = witness['N']
    if N != 12:
        raise VerificationError('N != 12')
    denoms = [factorial(n) - 1 for n in range(2, N + 1)]
    if denoms != witness['denominators']:
        raise VerificationError('denominator list mismatch')
    for i in range(len(denoms)):
        for j in range(i + 1, len(denoms)):
            if gcd(denoms[i], denoms[j]) != 1:
                raise VerificationError('pairwise coprimality failed: (%d, %d)' % (denoms[i], denoms[j]))
    L = sum(Fraction(1, d) for d in denoms)
    tail = Fraction(2 * (N + 2), (N + 1) * factorial(N + 1))
    if tail != Fraction(witness['tail_num'], witness['tail_den']):
        raise VerificationError('tail bound value mismatch')
    if not (tail < Fraction(3, factorial(N + 1))):
        raise VerificationError('tail bound inequality failed')
    if not (L * 10**11 > witness['interval_low_10_11']):
        raise VerificationError('lower interval endpoint failed')
    if not ((L + tail) * 10**11 < witness['interval_high_10_11']):
        raise VerificationError('upper interval endpoint failed')
    return True
